};


/**
 * 신규상장시 LP정보를 입력한 갯수만큼 데이타 셋에 저장
 */
/**
 * @method
 * @name fn_setLPGridData
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} vKey desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setLPGridData = function(dtsObj, vKey) {
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        var vLpMbrNo = dtsObj.getCellData(i, "LP_MBR_NO");
        if (vLpMbrNo != " " && vLpMbrNo != "") {
            //alert('[vLpMbrNo>>>>>>>]'+vLpMbrNo);
            dtsObj.setCellData(i, "BZ_PROCS_NO", vKey);
            dtsObj.setCellData(i, "LP_CONTRT_DD", ''); //not null -> null
            dtsObj.setCellData(i, "LP_STRT_DD", ''); //not null -> null

        } else {
            dtsObj.DeleteRow(i);
            i--; // 삭제한 경우는 해당하는 위치에서 한번더 검색하게 함.

        }
    }
};




/**
 * 신규상장시 분배기준일정보를 입력한 갯수만큼 데이타 셋에 저장
 */
/**
 * @method
 * @name fn_setDistrPayGridData
 * @description desc
 * @param {string} dtsObjSave desc
 * @param {string} dtsObj desc
 * @param {string} vKey desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setDistrPayGridData = function(dtsObjSave, dtsObj, vKey) {
    dtsObjSave.ClearData();
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        var vStdMM = dtsObj.getCellData(i, "EARNG_DISTR_BAS_MM");
        if (vStdMM != "") {
            dtsObjSave.AddRow();
            dtsObjSave.setCellData(i, "BZ_PROCS_NO", vKey);
            dtsObjSave.setCellData(i, "FISCYY_DISTR_BASDD_TP_CD", '2');
            dtsObjSave.setCellData(i, "EARNG_DISTR_BAS_MM", dtsObj.getCellData(i, "EARNG_DISTR_BAS_MM"));
            dtsObjSave.setCellData(i, "EARNG_DISTR_BAS_DD", dtsObj.getCellData(i, "EARNG_DISTR_BAS_DD"));
        }
    }
};





/**
 * 신규상장시 신용평가 정보를 입력한 갯수만큼 데이타 셋에 저장
 */
/**
 * @method
 * @name fn_setCreDitGridData
 * @description desc
 * @param {string} dtsObjSave desc
 * @param {string} dtsObj1 desc
 * @param {string} dtsObj2 desc
 * @param {string} vKey desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setCreDitGridData = function(dtsObjSave, dtsObj1, dtsObj2, vKey) {
    dtsObjSave.ClearData();
    for (var i = 1; i <= dtsObj1.getTotalRow(); i++) {
        dtsObjSave.AddRow();
        dtsObjSave.setCellData(i, "BZ_PROCS_NO", vKey);
        dtsObjSave.setCellData(i, "CREDIT_GRD_CONTN", dtsObj1.getCellData(i, "CREDIT_GRD_CONTN"));
        dtsObjSave.setCellData(i, "CREDIT_VALU_INST_TP_CD", dtsObj1.getCellData(i, "CREDIT_VALU_INST_TP_CD"));
    }
    for (var i = 1; i <= dtsObj2.getTotalRow(); i++) {
        var k = eval(parseInt(i)) + 3;
        dtsObjSave.AddRow();
        dtsObjSave.setCellData(k, "BZ_PROCS_NO", vKey);
        dtsObjSave.setCellData(k, "CREDIT_GRD_CONTN", dtsObj2.getCellData(i, "CREDIT_GRD_CONTN"));
        dtsObjSave.setCellData(k, "CREDIT_VALU_INST_TP_CD", dtsObj2.getCellData(i, "CREDIT_VALU_INST_TP_CD"));
    }
};
checkDateTPlus2;
checkDateTMinus2;
/**
	 * 기준일(T)을 사용
	    T-2, T+2일을 조회하는데 사용
	 */
/**
 * @method
 * @name fn_CheckValidDate
 * @description desc
 * @param {string} mktHoldyYn desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckValidDate = function(mktHoldyYn, obj) {
    url = "/etn/EtnIssueBook.do";
    url += "?method=checkValidDate&inputMessageId=ETN_ISUBOOK_VALID_INOUT";
    url += "&V_EXP_DD=" + obj.getValue();
    url += "&V_MKT_HOLDY_YN=" + mktHoldyYn;
    dts_getValDt.DataID = encodeURI(url);
    dts_getValDt.Reset();
    scwin.checkDateTMinus2 = dts_getValDt.getCellData(1, "CALND_DD");
    scwin.checkDateTPlus2 = dts_getValDt.getCellData(2, "CALND_DD");
};


/**
 * 첫번째입력 글자가 ('0', '-')인 경우 첫번째 글자 제거
 * (주의: text type은 해당되지 않음)
 */
/**
 * @method
 * @name fn_KeyUpCheckNumber
 * @description desc
 * @param {string} edtobj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_KeyUpCheckNumber = function(edtobj) {
    var val2 = $c.ut.trim(edtobj.getText());
    if (val2 == "-") {
        edtobj.setValue("0");
        val2 = "0";
    } else if (val2 == "") {
        val2 = "0";
    }
    if (val2.length > 1) {
        if (val2.substring(0, 1) == "0" || val2.substring(0, 1) == "-") {
            edtobj.setValue(val2.substring(1));
        }
    }
};




/**
 * 발행회사에 관한 사항: 발행한도(B/A)
 */
/**
 * @method
 * @name calcAmt
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.calcAmt = function() {
    edt_ISU_LIMIT.setValue("");
    var val1 = edt_ISU_TOTAMT.getValue();
    var val2 = edt_EQTYCAP.getValue();
    //if(val2 == "0" || val2 == "" || val1 == "" ) return;	
    if (val1 == "") return;
    val1 = new Number(val1);
    val2 = new Number(val2);
    //var val3 = (val1 / val2) *100;
    var val3 = Math.floor(val1 * 100 / val2 * 100) / 100;
    edt_ISU_LIMIT.setValue(new String(val3));
};


/**
 * 보증인에 관한 사항: 발행한도((B+C)/A)
 * 발행한도 = (발행총액 + 기타발행금액) / 자기자본
 */
/**
 * @method
 * @name calcAmtSrty
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.calcAmtSrty = function() {
    txb_limit_srty.setValue("");
    if (txb_SRTY_EQTYCAP.getText() == "0" || txb_SRTY_EQTYCAP.getText() == "" ||
        txb_SRTY_ISU_TOTAMT.getText() == "" || txb_SRTY_MISC_ISU_AMT.getText() == "") return;
    var val1 = new Number(txb_SRTY_EQTYCAP.getText()); //자기자본
    var val2 = new Number(txb_SRTY_ISU_TOTAMT.getText()); //발행총액
    var val3 = new Number(txb_SRTY_MISC_ISU_AMT.getText()); //기타발행금액
    //var val4 = ( (val2+val3) /val1 ) *100 ;
    var val4 = Math.floor((val2 + val3) * 100 / val1 * 100) / 100;
    txb_limit_srty.setValue(new String(val4));
};


/**
 * 보증인에 관한 사항:  자기자본 비율(%)(a/b) 
 * 최근분기말(1)/반기말(2)/사업년도말(3)
 */
/**
 * @method
 * @name calcAmtSrtyRto
 * @description desc
 * @param {string} pbIndex desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.calcAmtSrtyRto = function(pbIndex) {
    var val1 = "";
    var val2 = "";
    if (pbIndex == "1") {
        txb_RTO1.setValue("");
        val1 = txb_BAS_EQTYCAP1.getText();
        val2 = txb_RISK_ASST_VAL1.getText();
        if (val2 == "0" || val1 == "" || val2 == "") return;
        txb_RTO1.setValue(scwin.calcRto(val1, val2));
    } else if (pbIndex == "2") {
        txb_RTO2.setValue("");
        val1 = txb_BAS_EQTYCAP2.getText();
        val2 = txb_RISK_ASST_VAL2.getText();
        if (val2 == "0" || val1 == "" || val2 == "") return;
        txb_RTO2.setValue(scwin.calcRto(val1, val2));
    } else if (pbIndex == "3") {
        txb_RTO3.setValue("");
        val1 = txb_BAS_EQTYCAP3.getText();
        val2 = txb_RISK_ASST_VAL3.getText();
        if (val2 == "0" || val1 == "" || val2 == "") return;
        txb_RTO3.setValue(scwin.calcRto(val1, val2));
    }
};



/**
 * 비율계산
 */
/**
 * @method
 * @name calcRto
 * @description desc
 * @param {string} v1 desc
 * @param {string} v2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.calcRto = function(v1, v2) {
    var val1 = new Number(v1);
    var val2 = new Number(v2);
    //var result = (val1/val2) *100;
    var result = Math.floor(val1 * 100 / val2 * 100) / 100;
    return new String(result);
};


/**
 * 발행증권에 관한 사항: 지표가치금액 계산
 */
/**
 * @method
 * @name calcIndicValAmt
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.calcIndicValAmt = function() {
    var val1 = edt_ETN_ISU_QTY.getValue();
    var val2 = edt_PER1SECU_INDIC_VAL.getValue();
    if (val2 == "-") {
        edt_PER1SECU_INDIC_VAL.setValue("0");
        val2 = "0";
    } else if (val2 == "") {
        val2 = "0";
    }
    if (val1 == "") return;
    if (val2.length > 1) {
        if (val2.substring(0, 1) == "0" || val2.substring(0, 1) == "-") {
            edt_PER1SECU_INDIC_VAL.setValue(val2.substring(1));
            val2 = val2.substring(1);
        }
    }
    val1 = new Number(val1);
    val2 = new Number(val2);
    var val3 = Math.floor(val1 * val2);
    edt_INDIC_VAL_AMT.setValue(new String(val3));
};


/*
 * 일자,시간 체크 함수
 * isCheckCurDate : 오늘 날짜를 포함해서 비교를 할지 여부 ( 유가 : 미포함, 코스닥 : 포함 )
 */
/**
 * @method
 * @name checkDdTm2
 * @description desc
 * @param {string} gubun desc
 * @param {string} obj desc
 * @param {string} msg desc
 * @param {string} checkCompareDate desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkDdTm2 = function(gubun, obj, msg, checkCompareDate) {
    if (obj.text.length != 8) {
        alert("[" + msg + "일]을 정확히 입력하세요.");
        return false;
    }
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (gubun == "currDate") {
        if (vCurDate >= obj.getValue()) {
            alert("[" + msg + "일]을 현재일 이후로 입력하세요.");
            return false;
        }
    } else if (gubun == "ExpDdTMinus2") {
        if (checkCompareDate != obj.getValue()) {
            alert("[" + msg + "일]은 [만기일(T) 기준 T-2]이어야 함.");
            return false;
        }
    } else if (gubun == "ExpDdTPlus2") {
        if (checkCompareDate > obj.getValue()) {
            alert("[" + msg + "일]은 [만기일(T) 기준 T+2]보다 작으면 안됨.");
            return false;
        }
    } else {

    }
    return true;
};


