//추가상장
/**
 * @method
 * @name fn_CheckFormAdd
 * @description desc
 * @param {string} pTabIndex desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckFormAdd = function(pTabIndex) {
    if (pTabIndex == "1") {
        if (txb_ISU_CD.getValue() == "") {
            alert("[종목]을 선택하세요.");
            return false;
        }
        if (txb_ISU_SRT_CD.getValue() == "") {
            alert("[종목단축코드]항목값이  없습니다.");
            return false;
        }
        if (txb_ISU_KOR_NM.getValue() == "") {
            alert("[한글종목명]을 입력하세요.");
            return false;
        }
        if (!$c.lce.fn_getCheckByte('한글종목명', txb_ISU_KOR_NM.getValue(), 80)) return false;
        if (txb_ISU_KOR_ABBRV.getValue() == "") {
            alert("[한글종목약명]을 입력하세요.");
            txb_ISU_KOR_ABBRV.focus();
            return false;
        }
        if (!$c.lce.fn_getCheckByte('한글종목약명', txb_ISU_KOR_ABBRV.getValue(), 40)) return false;
        if (txb_ISU_ENG_NM.getValue() == "") {
            alert("[영문종목명]을 입력하세요.");
            return false;
        }
        if (!$c.lce.fn_getCheckByte('영문종목명', txb_ISU_ENG_NM.getValue(), 80)) return false;
        if (txb_ISU_ENG_ABBRV.getValue() == "") {
            alert("[영문종목약명]을 입력하세요.");
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.lce.fn_getCheckByte('영문종목약명', txb_ISU_ENG_ABBRV.getValue(), 40)) return false;
        if (edt_ETN_ISU_QTY.getValue() == "") {
            alert("[추가발행수량]을 입력하세요.");
            return false;
        }
        if (edt_ISU_ORGN_VAL.getValue() == "") {
            alert("[추가발행원본액]을 입력하세요.");
            return false;
        }
        if (edt_ISU_ORGN_VAL.getValue() < 0) {
            alert("[추가발행원본액]은 양수만 입력가능합니다.");
            return false;
        }
        if (edt_ISU_DD.getValue() == "") {
            alert("[추가발행일]을 입력하세요.");
            edt_ISU_DD.focus();
            return false;
        }
        if (txb_IDX_NM.getValue() == "") {
            alert("[기초지수명]을 입력하세요.");
            return false;
        }
        if (txb_IDX_CALC_INST_NM.getValue() == "") {
            alert("[지수산출기관]을 입력하세요.");
            return false;
        }
        if (cmb_ISU_AGNT_TP_CD.getValue() == "") {
            alert("[발행대행기관]을 입력하세요.");
            return false;
        }
        if (cmb_ETN_BZ_ADM_COM_TP_CD.getValue() == "") {
            alert("[사무관리회사]을 입력하세요.");
            return false;
        }
        if (edt_EXP_DD.getValue() == "") {
            alert("[만기일]을 입력하세요.");
            return false;
        }
        if (!$c.lcd.compareFromToDate(edt_ISU_DD, edt_EXP_DD, "추가발행일", "만기일")) return false;
        if (cmb_TAX_TP_CD.getValue() == "") {
            alert("[과세유형]을 입력하세요.");
            return false;
        }
        if (txb_IDX_LVRG_INVRS_TP_NM.getValue() == "") {
            alert("[추적배수]을 입력하세요.");
            return false;
        }
        if (cmb_DISTR_TP_CD.getValue() == "") {
            alert("[분배금형태]을 입력하세요.");
            return false;
        }
        if (txb_DISTR_PAY_BAS_DD_CONTN.getValue() == "") {
            alert("[분배금지급기준일]을 입력하세요.");
            return false;
        }
        if (!$c.lce.fn_getCheckByte('분배금지급기준일', txb_DISTR_PAY_BAS_DD_CONTN.getValue(), 200)) return false;
        if (txb_DISTR_PAY_DD_CONTN.getValue() == "") {
            alert("[분배금지급일]을 입력하세요.");
            return false;
        }
        if (!$c.lce.fn_getCheckByte('분배금지급일', txb_DISTR_PAY_DD_CONTN.getValue(), 200)) return false;
        scwin.fn_CheckValidDate('N', edt_EXP_DD); //만기일(T) 기준T-2, T+2 조회

        /* 최종거래일은 만기일(T) 기준 T-2이어야 함(거래일 기준)*/
        if (!scwin.checkDdTm2("ExpDdTMinus2", edt_LSTTRD_DD, "최종거래", scwin.checkDateTMinus2)) return false;
        if (edt_LP_HD_QTY.getValue() == "") {
            alert("[LP보유수량]을 입력하세요.");
            return false;
        }
        if (edt_DECL_SPD.getValue() == "") {
            alert("[신고스프레드]을 입력하세요.");
            return false;
        }
        if (edt_HALFWY_REDMPT_UNIT.getValue() == "") {
            alert("[중도상환단위]을 입력하세요.");
            edt_HALFWY_REDMPT_UNIT.focus();
            return false;
        }
        if (!scwin.checkDdTm2("ChkEmpty", edt_EXP_REDMPT_PRC_DECSN_STRT_DD, "만기상환가격 결정 시작")) return false;
        if (!scwin.checkDdTm2("ChkEmpty", edt_EXP_REDMPT_PRC_DECSN_END_DD, "만기상환가격 결정 종료")) return false;
        if (!$c.lcd.compareFromToDate(edt_EXP_REDMPT_PRC_DECSN_STRT_DD, edt_EXP_REDMPT_PRC_DECSN_END_DD, "만기상환가격 결정 시작일", "종료일")) return false;

        /* 만기상환금 지급일은 만기일(T) 기준 T+2 보다 작으면 안됨(거래일 기준)*/
        if (!scwin.checkDdTm2("ExpDdTPlus2", edt_EXP_REDMPT_AMT_PAY_DD, "만기상환금 지급", scwin.checkDateTPlus2)) return false;
        if (txb_HALFWY_REDMPT_APPL_CYCLE_CONTN.getValue() == "") {
            alert("[중도상환 신청주기]을 입력하세요.");
            txb_HALFWY_REDMPT_APPL_CYCLE_CONTN.focus();
            return false;
        }
        if (!$c.lce.fn_getCheckByte('중도상환 신청주기', txb_HALFWY_REDMPT_APPL_CYCLE_CONTN.getValue(), 50)) return false;
        if (txb_HALFWY_REDMPT_PRC_DECSN_CONTN.getValue() == "") {
            alert("[중도상환가격 결정일]을 입력하세요.");
            txb_HALFWY_REDMPT_PRC_DECSN_CONTN.focus();
            return false;
        }
        if (!$c.lce.fn_getCheckByte('중도상환가격 결정일', txb_HALFWY_REDMPT_PRC_DECSN_CONTN.getValue(), 200)) return false;
        if (txb_HALFWY_REDMPT_AMT_PAY_DD_CONTN.getValue() == "") {
            alert("[중도상환금 지급일]을 입력하세요.");
            txb_HALFWY_REDMPT_AMT_PAY_DD_CONTN.focus();
            return false;
        }
        if (!$c.lce.fn_getCheckByte('중도상환금 지급일', txb_HALFWY_REDMPT_AMT_PAY_DD_CONTN.getValue(), 200)) return false;
        if (cmb_LST_SETL_METHD_CD.getValue() == "") {
            alert("[결제방법]을 입력하세요.");
            return false;
        }
        if (edt_LIST_DD.getValue() == "") {
            alert("[추가상장일지정]을 입력하세요.");
            edt_LIST_DD.focus();
            return false;
        }
        if (!scwin.checkDdTm2("currDate", edt_LIST_DD, "추가상장", "")) return false;
        if (!$c.lcd.compareFromToDate(edt_LIST_DD, edt_EXP_DD, "추가상장일", "만기일")) return false;
